import Dexie, { type EntityTable } from 'dexie'
import type { RepRecord, SessionRecord } from '../engine/types'
import type { SettingsRecord } from './settings-types'
import type { ProfileRecord } from './profiles'

export class ReactorDB extends Dexie {
  sessions!: EntityTable<SessionRecord, 'id'>
  reps!: EntityTable<RepRecord, 'id'>
  settings!: EntityTable<SettingsRecord, 'id'>
  profiles!: EntityTable<ProfileRecord, 'id'>

  constructor() {
    super('pointfight-reactor')
    this.version(1).stores({
      sessions: 'id, startedAt',
      reps: 'id, sessionId, cueId',
    })
    this.version(2).stores({
      sessions: 'id, startedAt',
      reps: 'id, sessionId, cueId',
      settings: 'id',
    })
    this.version(3).stores({
      sessions: 'id, startedAt',
      reps: 'id, sessionId, cueId',
      settings: 'id',
      profiles: 'id, createdAt',
    })
  }
}

let _db: ReactorDB | null = null
let _openError: Error | null = null

export function getDb(): ReactorDB | null {
  if (_db) return _db
  if (_openError) return null
  try {
    _db = new ReactorDB()
    return _db
  } catch (err) {
    _openError = err instanceof Error ? err : new Error(String(err))
    return null
  }
}

export function getDbError(): Error | null {
  return _openError
}

export async function saveSession(session: SessionRecord): Promise<void> {
  const db = getDb()
  if (!db) return
  try {
    await db.sessions.put(session)
  } catch (err) {
    _openError = err instanceof Error ? err : new Error(String(err))
  }
}

export async function saveRep(rep: RepRecord): Promise<void> {
  const db = getDb()
  if (!db) return
  try {
    await db.reps.put(rep)
  } catch (err) {
    _openError = err instanceof Error ? err : new Error(String(err))
  }
}

export async function listRecentSessions(limit = 20): Promise<SessionRecord[]> {
  const db = getDb()
  if (!db) return []
  try {
    return await db.sessions
      .orderBy('startedAt')
      .reverse()
      .limit(limit)
      .toArray()
  } catch {
    return []
  }
}

/**
 * Bulk-fetch reps for a set of sessionIds, grouped by sessionId. Sessions in
 * `sessionIds` that have no reps still appear in the result with an empty
 * array — callers can rely on Map.get(id) returning [], not undefined.
 */
export async function listRepsForSessions(
  sessionIds: string[],
): Promise<Map<string, RepRecord[]>> {
  const out = new Map<string, RepRecord[]>()
  for (const id of sessionIds) out.set(id, [])
  if (sessionIds.length === 0) return out
  const db = getDb()
  if (!db) return out
  try {
    const reps = await db.reps.where('sessionId').anyOf(sessionIds).toArray()
    for (const r of reps) {
      const list = out.get(r.sessionId)
      if (list) list.push(r)
    }
  } catch {
    /* fall through with whatever was groupable */
  }
  return out
}

import { Suspense, lazy, useEffect, useState } from 'react'
import { useSession } from './store/session'
import {
  DEFAULT_SETTINGS,
  loadSettings,
  type SettingsRecord,
} from './store/settings'
import { IdleScreen } from './ui/IdleScreen'
import { TrainerScreen } from './ui/TrainerScreen'
import { SummaryScreen } from './ui/SummaryScreen'
import { SettingsScreen } from './ui/SettingsScreen'
import { AnalyticsScreen } from './ui/AnalyticsScreen'
import './App.css'

const PairScreen = lazy(() =>
  import('./ui/PairScreen').then((m) => ({ default: m.PairScreen })),
)

type IdleView = 'idle' | 'settings' | 'analytics' | 'pair'

function App() {
  const phase = useSession((s) => s.phase)
  const [view, setView] = useState<IdleView>('idle')
  // Remember which view sent the user to pair so closing returns there.
  const [pairOpener, setPairOpener] = useState<'idle' | 'settings'>('settings')
  const [settings, setSettings] = useState<SettingsRecord>(DEFAULT_SETTINGS)

  useEffect(() => {
    void loadSettings().then(setSettings)
  }, [view])

  if (view === 'settings') {
    return (
      <SettingsScreen
        onClose={() => setView('idle')}
        onOpenPair={() => {
          setPairOpener('settings')
          setView('pair')
        }}
      />
    )
  }
  if (view === 'analytics') {
    return <AnalyticsScreen onClose={() => setView('idle')} />
  }
  if (view === 'pair') {
    return (
      <Suspense fallback={<div className="screen">Loading pair UI…</div>}>
        <PairScreen onClose={() => setView(pairOpener)} />
      </Suspense>
    )
  }
  if (phase === 'idle')
    return (
      <IdleScreen
        onOpenSettings={() => setView('settings')}
        onOpenAnalytics={() => setView('analytics')}
        onOpenPair={() => {
          setPairOpener('idle')
          setView('pair')
        }}
      />
    )
  if (phase === 'ended') return <SummaryScreen />
  return (
    <TrainerScreen
      commitKeyCode={settings.commitKeyCode}
      commitKeyLabel={settings.commitKeyLabel}
    />
  )
}

export default App

import { useEffect, useState } from 'react'
import { listRecentSessions } from '../store/db'
import { useSession } from '../store/session'
import {
  DEFAULT_SETTINGS,
  loadActiveProfile,
  loadSettings,
  type SettingsRecord,
} from '../store/settings'
import type { ProfileRecord } from '../store/profiles'
import type { SessionRecord } from '../engine/types'
import { usePhonePeer } from '../store/phone-peer'

interface IdleScreenProps {
  onOpenSettings: () => void
  onOpenAnalytics: () => void
  /** Phase 2b.4 — present so the "Phone not paired — pair now" banner button has a destination. */
  onOpenPair?: () => void
}

export function IdleScreen({
  onOpenSettings,
  onOpenAnalytics,
  onOpenPair,
}: IdleScreenProps) {
  const start = useSession((s) => s.start)
  const [recent, setRecent] = useState<SessionRecord[]>([])
  const [settings, setSettings] = useState<SettingsRecord>(DEFAULT_SETTINGS)
  const [profile, setProfile] = useState<ProfileRecord | null>(null)
  const phoneStatus = usePhonePeer((s) => s.status)

  useEffect(() => {
    void listRecentSessions(5).then(setRecent)
    void loadSettings().then(setSettings)
    void loadActiveProfile().then(setProfile)
  }, [])

  const phoneSelected = settings.inputSource === 'phone'
  const phoneReady = phoneStatus === 'connected'
  const startDisabled = !profile || (phoneSelected && !phoneReady)

  function handleStart() {
    if (startDisabled) return
    void requestFullscreen()
    if (!profile) return
    start(profile.config, undefined, settings.inputSource)
  }

  return (
    <div className="screen idle">
      <h1>PointFight Reactor</h1>
      <p className="subtitle">First-beat go / no-go drill</p>

      {settings.inputSource === 'keyboard' && (
        <div className="banner info">
          Keyboard mode — foot pedal recommended for live drilling.
        </div>
      )}

      {phoneSelected && !phoneReady && (
        <div
          className="banner warn"
          role="status"
          data-testid="phone-not-paired"
        >
          Phone not paired —{' '}
          {onOpenPair ? (
            <button
              type="button"
              className="link"
              onClick={onOpenPair}
              aria-label="pair phone now"
            >
              pair now
            </button>
          ) : (
            <span>open Settings → Pair phone</span>
          )}
          .
        </div>
      )}

      {profile && (
        <p className="active-profile">
          Profile: <strong>{profile.name}</strong>
        </p>
      )}

      <button
        className="primary"
        type="button"
        onClick={handleStart}
        disabled={startDisabled}
        autoFocus
      >
        Start drill
      </button>
      <p className="hint">
        Press <kbd>{settings.commitKeyLabel}</kbd> to commit. Press{' '}
        <kbd>Esc</kbd> to stop.
      </p>

      <div className="idle-links">
        <button type="button" className="link" onClick={onOpenSettings}>
          Settings
        </button>
        <button type="button" className="link" onClick={onOpenAnalytics}>
          Analytics
        </button>
      </div>

      {recent.length > 0 && (
        <div className="recent">
          <h2>Recent sessions</h2>
          <ul>
            {recent.map((s) => (
              <li key={s.id}>
                <span className="when">
                  {new Date(s.startedAt).toLocaleString()}
                </span>
                <span className="meta">
                  {s.repCount} reps · score {s.summary.score}
                  {s.summary.avgReactionMs !== null &&
                    ` · ${s.summary.avgReactionMs}ms avg`}
                  {s.inputSource && ` · ${s.inputSource}`}
                </span>
              </li>
            ))}
          </ul>
        </div>
      )}
    </div>
  )
}

async function requestFullscreen(): Promise<void> {
  try {
    if (document.fullscreenElement) return
    await document.documentElement.requestFullscreen()
  } catch {
    /* user can run windowed; no-op */
  }
}

import { beforeEach, describe, expect, it } from 'vitest'
import { getDb, listRepsForSessions, saveRep, saveSession } from './db'
import type { RepRecord, SessionRecord } from '../engine/types'

async function clear() {
  const db = getDb()
  if (!db) return
  await db.reps.clear()
  await db.sessions.clear()
}

function makeSession(id: string, startedAt: number): SessionRecord {
  return {
    id,
    startedAt,
    endedAt: startedAt + 1000,
    drillType: 'first_beat_go_no_go',
    repCount: 0,
    summary: {
      reps: 0,
      correct: 0,
      falseStarts: 0,
      lateMisses: 0,
      hesitations: 0,
      score: 0,
      avgReactionMs: null,
    },
  }
}

function makeRep(id: string, sessionId: string): RepRecord {
  return {
    id,
    sessionId,
    cueId: 'steps_in',
    isGo: true,
    result: 'correct_go',
    reactionMs: 300,
    score: 1,
    cueShownAt: 0,
    pressedAt: 0,
    roundIndex: 0,
    inputSource: 'keyboard',
  }
}

describe('listRepsForSessions', () => {
  beforeEach(async () => {
    await clear()
  })

  it('groups reps by sessionId for the supplied IDs', async () => {
    await saveSession(makeSession('s1', 1000))
    await saveSession(makeSession('s2', 2000))
    await saveRep(makeRep('r1', 's1'))
    await saveRep(makeRep('r2', 's1'))
    await saveRep(makeRep('r3', 's2'))

    const map = await listRepsForSessions(['s1', 's2'])
    expect(map.get('s1')?.map((r) => r.id).sort()).toEqual(['r1', 'r2'])
    expect(map.get('s2')?.map((r) => r.id)).toEqual(['r3'])
  })

  it('returns an empty array (not undefined) for a sessionId with no reps', async () => {
    await saveSession(makeSession('empty', 1000))
    const map = await listRepsForSessions(['empty'])
    expect(map.get('empty')).toEqual([])
  })

  it('returns an empty map when given no sessionIds', async () => {
    const map = await listRepsForSessions([])
    expect(map.size).toBe(0)
  })

  it('does not include reps from sessions outside the requested set', async () => {
    await saveRep(makeRep('r1', 'wanted'))
    await saveRep(makeRep('r2', 'other'))
    const map = await listRepsForSessions(['wanted'])
    expect(map.get('wanted')?.map((r) => r.id)).toEqual(['r1'])
    expect(map.has('other')).toBe(false)
  })
})

