        empty_hint: emptyHint,
        import_label: importLabel,
        close_button: closeBtn,
      }
      await screenshot(page, 'C2-library-empty.png')
      await ctx.close()
    }

    // ---------- C3. Quota text renders when storage.estimate is available ----------
    {
      const ctx = await browser.newContext()
