1	import { getDb } from '../store/db'
2	import {
3	  CLIP_HARD_CAP_BYTES,
4	  CLIP_SOFT_WARN_BYTES,
5	  SUPPORTED_CLIP_MIME_TYPES,
6	  type AddClipResult,
7	  type ClipRecord,
8	} from './types'
9	
10	function mintClipId(now: number): string {
11	  return `clip-${now.toString(36)}-${Math.random().toString(36).slice(2, 9)}`
12	}
13	
14	function isQuotaError(err: unknown): boolean {
15	  if (err instanceof DOMException) {
16	    return err.name === 'QuotaExceededError' || err.code === 22
17	  }
18	  if (err && typeof err === 'object' && 'name' in err) {
19	    return (err as { name?: string }).name === 'QuotaExceededError'
20	  }
21	  return false
22	}
23	
24	function errorMessage(err: unknown): string {
25	  if (err instanceof Error) return err.message
26	  return String(err)
27	}
28	
29	export async function addClip(
30	  file: File,
31	  opts: { durationMs: number },
32	): Promise<AddClipResult> {
33	  const db = getDb()
34	  if (!db) {
35	    return {
36	      ok: false,
37	      reason: 'storage-error',
38	      message: 'Database is unavailable.',
39	    }
40	  }
41	
42	  if (!SUPPORTED_CLIP_MIME_TYPES.includes(file.type)) {
43	    return {
44	      ok: false,
45	      reason: 'unsupported-type',
46	      message: `File type ${file.type || '(unknown)'} is not supported. Use .mp4.`,
47	    }
48	  }
49	
50	  if (file.size > CLIP_HARD_CAP_BYTES) {
51	    const mb = Math.round(file.size / 1024 / 1024)
52	    return {
53	      ok: false,
54	      reason: 'too-large',
55	      message: `Clip is ${mb} MB; the per-clip limit is ${CLIP_HARD_CAP_BYTES / 1024 / 1024} MB.`,
56	    }
57	  }
58	
59	  const clip: ClipRecord = {
60	    id: mintClipId(Date.now()),
61	    name: file.name,
62	    mimeType: file.type,
63	    durationMs: Math.max(0, Math.round(opts.durationMs)),
64	    sizeBytes: file.size,
65	    importedAt: Date.now(),
66	    blob: file,
67	  }
68	
69	  try {
70	    await db.clips.put(clip)
71	  } catch (err) {
72	    if (isQuotaError(err)) {
73	      return {
74	        ok: false,
75	        reason: 'quota',
76	        message:
77	          'Browser storage quota exceeded. Delete a clip before importing more.',
78	      }
79	    }
80	    return { ok: false, reason: 'storage-error', message: errorMessage(err) }
81	  }
82	
83	  return { ok: true, clip }
84	}
85	
86	export async function listClips(): Promise<ClipRecord[]> {
87	  const db = getDb()
88	  if (!db) return []
89	  try {
90	    return await db.clips.orderBy('importedAt').reverse().toArray()
91	  } catch {
92	    return []
93	  }
94	}
95	
96	export async function deleteClip(id: string): Promise<void> {
97	  const db = getDb()
98	  if (!db) return
99	  try {
100	    await db.clips.delete(id)
101	  } catch {
102	    /* leave the row in place; UI can retry */
103	  }
104	}
105	
106	export interface QuotaEstimate {
107	  usageBytes: number
108	  quotaBytes: number
109	  /** 0..1; quotaBytes can be 0 on browsers that decline to report. */
110	  percent: number
111	}
112	
113	export async function getQuotaEstimate(): Promise<QuotaEstimate | null> {
114	  if (typeof navigator === 'undefined' || !navigator.storage?.estimate) {
115	    return null
116	  }
117	  try {
118	    const est = await navigator.storage.estimate()
119	    const usage = est.usage ?? 0
120	    const quota = est.quota ?? 0
121	    return {
122	      usageBytes: usage,
123	      quotaBytes: quota,
124	      percent: quota > 0 ? usage / quota : 0,
125	    }
126	  } catch {
127	    return null
128	  }
129	}
130	
131	export function isSoftWarnSize(bytes: number): boolean {
132	  return bytes > CLIP_SOFT_WARN_BYTES && bytes <= CLIP_HARD_CAP_BYTES
